        if day < 0: raise ValueError()
    except ValueError:
        raise ValueError(f"Bad day: {day_s}")

    type_u = type_s.upper()
    if type_u not in {"RCV", "SHP", "RTN", "ADJ"}:
        raise ValueError(f"Unknown type: {type_u}")

    sku = normalize_sku(sku_s)
    zone, aisle, shelf, level = parse_location(loc_s)
    loc_canonical = f"{zone}-{aisle:02d}-{shelf:02d}-{level}"

    cs = case_sizes.get(sku, 1)
