    if type_u in {"RCV", "SHP", "RTN"} and raw_qty <= 0:
        raise ValueError(f"Non-positive quantity for {type_u}")
    if type_u == "ADJ" and raw_qty == 0:
        raise ValueError("Zero ADJ rejected")

    if type_u == "SHP":
        qty = -raw_qty
    elif type_u in {"RCV", "RTN"}:
        qty = raw_qty
    else:
