from typing import Any, Dict, Mapping
from stockflow.normalize_sku import normalize_sku
from stockflow.parse_location import parse_location
from stockflow.parse_quantity import parse_quantity


def parse_movement_line(line: str, case_sizes: Mapping[str, int]) -> Dict[str, Any]:
    parts = [p.strip() for p in line.split(";")]
    if len(parts) != 5:
        raise ValueError("Wrong number of fields")

    day_s, type_s, sku_s, loc_s, qty_s = parts

    try:
        day = int(day_s)
        if day < 0: raise ValueError()
    except ValueError:
        raise ValueError(f"Invalid day: {day_s}")

    type_u = type_s.upper()
    if type_u not in {"RCV", "SHP", "RTN", "ADJ"}:
        raise ValueError(f"Unknown type: {type_u}")

    sku = normalize_sku(sku_s)
    zone, aisle, shelf, level = parse_location(loc_s)
    loc_canonical = f"{zone}-{aisle:02d}-{shelf:02d}-{level}"

    cs = case_sizes.get(sku, 1)
    raw_qty = parse_quantity(qty_s, cs)

    if type_u in {"RCV", "SHP", "RTN"} and raw_qty <= 0:
        raise ValueError(f"Non-positive quantity for {type_u}")
    if type_u == "ADJ" and raw_qty == 0:
        raise ValueError("Zero ADJ rejected")

    if type_u == "SHP":
        qty = -raw_qty
    elif type_u in {"RCV", "RTN"}:
        qty = raw_qty
    else:
        qty = raw_qty

    return {"day": day, "type": type_u, "sku": sku, "location": loc_canonical, "qty": qty}"}}, "messages": []}

